 wRRepetCtrlValue = 0;INT16S wRRepetCtrlValue1 = 0;INT16S wRRepetCtrlUp;INT16S wRRepetCtrUnder;INT16S wKRctrl1;INT16S wKRctrl2;INT16S wOPShareCurrCntl;INT16S wOPShareCurrCntl_1;INT16S wOPShareCurrCntl_Filter;INT16S wOPShareCurrCntlErr;INT16S wOPShareCurrCntlErr_1;INT16S wOPShareCurrCntlErr_Filter;INT16S wOPShareCurrCntlVoltVal;INT16S wKs = 24;INT16S g_wInvDCVoltCntl;INT16S  g_wFBCtrlStartCycle = true;INT16S  g_wFBCtrlStartPoint = 0;INT16S wFB_VoltPI_Kp=158;INT16S wFB_VoltPI_Ki=54;INT16S wVerr_P;INT16S wVerr_P_1;INT32S dwFBP_Ierr;INT32S dwFBP_VoltPI;INT32S dwFBP_VoltPI_K;INT32S dwFBP_VoltPI_I;INT32S dwFBP_VoltPI_I_Res;INT16S wVmUpLimit =9000;INT16S wVm_P;INT16S wLineVoltCntlQ5;         // Q5INT16S wGenVoltCntlQ5;INT16S gi_wLineVoltQ5_0;     // Q5INT16S wR_Vac_P;INT16S wConverterTemp;INT16S wR_Imo_P;INT16S wKCurrentFeedback = 15;INT16S wKCurrentForward = 100;INT16S wR_Is_P;INT16S wR_Ierr_P;INT16S wR_PrevVcmp_P =0;INT16S wR_Vcmp_P;INT16S wR_Ierr_P_1;INT16S wR_Vcmp_P_1;INT32S dwR_Vcmp_P;INT16S wR_Vcmp_PRes;INT16S wR_PredIerr_P;INT16S wFB_Duty;INT16S g_dwFBBusRealAvgSum;INT32S dwFBP_CurPI;INT32S dwFBP_CurPI_K;INT32S dwFBP_CurPI_I;INT32S  dwFBP_CurPI_I_Res;INT16S wFB_CurPI_Ki =164;INT16S wMaxVmUpLimit =5000;INT16S wFBP_VoltPIAdjCtl =0;INT16U  wNPWMForwardFlg = 2;INT16U  wLPWMForwardFlg = 2;INT16S wOpenSinRef;INT16S IsoReverseCnt =0;INT16S IsoReverseFlag =0;INT16S IsoReverseRecoverCnt =0;INT16S IsoReverseChkCnt =0;INT16S wRKvBase;INT16S wRKiBase;INT16S wKCurrentForwardAdj =0;INT16S wInvLoopCntPre = 0;INT16S wInvLoopCntLast = 0;F32 fDisChgCurrLoopI = 0.0;F32 fDisChgCurrLoopP = 0.0;F32 fDisChgCurrLoopPI = 0.0;F32 fDisChgCurrLoopErr0 = 0.0;F32 fDisChgCurrLoopErr1 = 0.0;F32 fDisChgCurrLoopErr2 = 0.0;F32 fDisChgCurrLoopOut0 = 0.0;F32 fDisChgCurrLoopOut1 = 0.0;F32 fDisChgCurrLoopOut2 = 0.0;F32 fDisChgCurrLoopRef = 0.0;//AC放电电流环F32   fDisChgCurrLoopSamp;F32   fDisChgPwm = 0.0;F32   fAcDisChgCurrLimit = 0.0;F32   fAcDisChgPowerLimit = 0.0;F32   fAcDisChgCurrError = 0.0;F32   fAcDisChgCurrLoopI = 0.0;F32   fAcDisChgCurrLoopOut = 0.0;F32 fInvVoltLoopI = 0.0;F32 fInvVoltLoopP = 0.0;F32 fInvVoltLoopPI = 0.0;F32 fInvVoltLoopErr0 = 0.0;F32 fInvVoltLoopErr1 = 0.0;F32 fInvVoltLoopErr2 = 0.0;F32 fInvVoltLoopOut0 = 0.0;F32 fInvVoltLoopOut1 = 0.0;F32 fInvVoltLoopOut2 = 0.0;//负载功率环F32 fLoadPowerPLimit = 12000;//12KWF32 fLoadPowerPLoopError = 0.0;F32 fLoadPowerPLoopI = 0.0;F32 fLoadPowerPLoopPI = 0.0;F32 fLoadPowerQLimit = 3000;//3KVarF32 fLoadPowerQLoopError = 0.0;F32 fLoadPowerQLoopI = 0.0;F32 fLoadPowerQLoopPI = 0.0;INT16S wInvZeroPointerFlag1 = 0;INT16S wInvZeroPointerFlag2 = 0;INT16S wParaDataSetFlag = true;INT16S wParaDataSetCnt = 0;/********************************************************************************* Internal routine prototypes                                                   *********************************************************************************/void sInverterControl(void);#pragma CODE_SECTION(sInverterControl,".TI.ramfunc");void    sFBINVController2(void);/********************************************************************************* Routines' implementations                                                     *********************************************************************************/void    sSet50HzParameter(void){    sSetInvStep(cINV_PWM_PERIOD);    wRCountsPerPeriod=384;    wROneThreeCountsPerPeriod = 128;    wRTwoThreeCountsPerPeriod = 256;    wInvVoltSampleCnt1=wRCountsPerPeriod>>2;    wRCountsHalfPeriod=wRCountsPerPeriod>>1;    wInvVoltSampleCnt3Div4 = ((wRCountsPerPeriod * 3) >> 2);    wInvVoltSampleCnt1Div8 = (wRCountsPerPeriod  >> 3)-1;    pSinTab=SinTab384;    pCosTab=CosTab384;    sSetInverterPeriodCntSet(cPeriod50Hz);}void    sSet60HzParameter(void){    sSetInvStep(cINV_PWM_PERIOD);    wRCountsPerPeriod=384;    wROneThreeCountsPerPeriod = 128;    wRTwoThreeCountsPerPeriod = 256;    wInvVoltSampleCnt1=wRCountsPerPeriod>>2;    wRCountsHalfPeriod=wRCountsPerPeriod>>1;    wInvVoltSampleCnt3Div4 = ((wRCountsPerPeriod * 3) >> 2);    wInvVoltSampleCnt1Div8 = (wRCountsPerPeriod  >> 3)-1;    pSinTab=SinTab384;    pCosTab=CosTab384;    sSetInverterPeriodCntSet(cPeriod60Hz);}INT8U sbInvVoltSoftStart(INT16U wTrackVolt, INT16U wTrackVoltStep){    INT16U wTrackVoltVp;    INT16U wTrackVoltStepVp;    INT16U wError;    wTrackVoltVp = (INT16U)(((INT32U)wTrackVolt * 362 * 32) >> 8);      //362>>8=1.414    wTrackVoltStepVp = (INT16U)(((INT32U)wTrackVoltStep * 362 * 32) >> 8);//5*1.414V    wError = wTrackVoltVp - wTrackVoltStepVp;    if(wRNewSinAmp < wError)    {        wRNewSinAmp = wRSinAmp + wTrackVoltStepVp;		wRNewSinAmpTemp=wRNewSinAmp;        return(false);    }    else    {        wRNewSinAmp = wTrackVoltVp;		wRNewSinAmpTemp=wRNewSinAmp;        return(true);    }}INT16S wDCVoltSet = 0;INT16S wVoltFeedK = 0;F32 fFreqAdjDelta = 0.0;F32 fFreqAdjDeltaLast = 0.0;F32 fVoltAdjDelta = 0.0;F32 fVoltAdjDeltaLast = 0.0;F32 fParlSinPointer;F32 fNewSinPointer;F32 fNewSinPointerDelta = 0.0;INT16S wOPShareCurrCntlThetaVal;INT16S wOPShareCurrCntlThetaVal;INT16S wOPShareCurrCntlThetaCompVal;INT16S wInvVoltCompValueTemp;INT16S wInvVoltCompValueReal = 0;//INT16S wInvVoltCompI;INT16S wVoltDropFeed;INT16S wInvCurrFeedValue;INT16S AvePowerWattLast = 0;extern INT16U       wRInverterVolt;void sUpdateInvCntlPara(void){    fParlSinPointer = (F32)wCtrlSinpointer;}F32 fVirIndcComp = 0.0;F32 fVirIndcCompLast = 0.0;INT16U uwInv2PwmOnFlag = 0;INT16S wInvCurrErr1 = 0;INT16S wInvVoltErr1 = 0;INT16S wInvVoltDcSamp = 0;void sInverterControl(void){	//F32 fRVrefTemp;	//F32 fRInvVoltCntlTemp;		//-----------------方案1--------------------------------	//跑一会会有相位差，调节不回来    //INT16S ftemp;    if(hoInv1Relay == 1 && mEepromOutputMode() != cOP_Single)    {        //----------------------------????------------------------------        //SOGIAdvanceInvCurr.OsgAcQOut[0]*32.0		//----------------------------虚拟电感------------------------------	    //-----------------------------调频---------------------------------        //fFreqAdjDelta =SogiInvPower.AcPowerQFilt[1] * 0.5f*0.00000347f;//16/384/12000=3.47e-6        fFreqAdjDelta =SogiInvPower.fAcPowerQFilt[1] * 0.5f*0.0000004f;//16/384/12000=3.47e-6        UP_DOWN_LIMIT(fFreqAdjDelta,0.054f,-0.054f);        if((fFreqAdjDelta - fFreqAdjDeltaLast)>0.0001f)        {            fFreqAdjDelta = fFreqAdjDeltaLast + 0.0001f;        }        else if((fFreqAdjDelta - fFreqAdjDeltaLast)<-0.0001f)        {            fFreqAdjDelta = fFreqAdjDeltaLast - 0.0001f;        }        fFreqAdjDeltaLast = fFreqAdjDelta;        fFreqAdjDelta = 0.0f;        fVoltAdjDelta =SogiInvPower.fAcPowerPFilt[1] * 0.5f*0.064f;//30*32/6000=0.01  0.4        UP_DOWN_LIMIT(fVoltAdjDelta,2000.0f,-2000.0f);        /*if((fVoltAdjDelta - fVoltAdjDeltaLast)>200.0f)        {            fVoltAdjDelta = fVoltAdjDeltaLast + 200.0f;        }        else if((fVoltAdjDelta - fVoltAdjDeltaLast)<-200.0f)        {            fVoltAdjDelta = fVoltAdjDeltaLast - 200.0f;        }        fVoltAdjDeltaLast = fVoltAdjDelta;*/        //fFreqAdjDelta = 0;        fParlSinPointer += (1.0f+fFreqAdjDelta);        if(fParlSinPointer >= (F32)gi_wPLLPointerMax)        {            fParlSinPointer -= (F32)gi_wPLLPointerMax;            wInvZeroPointerFlag1 = 1;            wInvZeroPointerFlag2 = 1;        }        if(wParaMode == cMasterMode)        {            fNewSinPointer = fParlSinPointer * 384.0/(F32)gi_wPLLPointerMax;        }        else        {            fNewSinPointer = fParlSinPointer * 384.0/(F32)gi_wPLLPointerMax;//+4.0f;        }        fNewSinPointer = (F32)wCtrlSinpointer;        if(fNewSinPointer > 384.0f)        {            fNewSinPointer -= 384.0f;        }        //fNewSinPointer = (F32)wCtrlSinpointer;		//-----------------------------调频---------------------------------*/    }    else    {        wOPShareCurrCntlVoltVal = 0;        fNewSinPointer = (F32)wCtrlSinpointer;        fParlSinPointer = (F32)wCtrlSinpointer;        fVoltAdjDelta = 0.0f;        fVirIndcComp = 0.0f;    }    if(abs(wInvVoltReal)  >= (gi_wInvOverValue-100)&&(g_wPhaseMasterFlg))    {        //wInvVoltCompValueReal = 0;        wInvVoltCompValueTemp = 0;        //wInvVoltCompI = 0;        wVoltDropFeed = 0;		wInvCurrFeedValue = 0;		wVoltRmsLoopI = 0;        if(wParaDataSetFlag)        {            wParaDataSetFlag = false;            OSEventSend(cPrioPara,eParaDataSet);        }    }	if(!wParaDataSetFlag)//防止持续发送占用CAN总线	{		wParaDataSetCnt++;		if(wParaDataSetCnt >=29)//2.5ms		{			wParaDataSetFlag = true;			wParaDataSetCnt = 0;		}	}	fRVref = ((F32)wRSinAmp - fVoltAdjDelta) * sinf(fNewSinPointer*0.01636f);//2*pi/384	wInvVoltErr1 = wRInvVoltCntl - (SogiInvVolt.fOsgAcAlpha[0] * 5002.5 * 3.2 + 0.5);	//wInvVoltDcSamp =(g_wInvVoltDcSamp * g_wInvVCntlFactor) >> 4;	wInvVoltDcSamp = 0;    fRInvVoltError = fRVref - (F32)wRInvVoltCntl;    UP_DOWN_LIMIT(fRInvVoltError,16500.0f,-16500.0f);	//电压环比例-------------------------start--------------------------------------	wVoltLoopTemp = (INT16S)((INT32S)fRInvVoltError * wRKv >> 7);        //   wRKv=10	//wVoltLoopTemp = (INT16S)((INT32S)fRInvVoltError * 12 >> 7);		   //使用参考做前馈    if(wVoltLoopTemp > wInvCrrentLimit << 5)    {        wVoltLoopTemp = wInvCrrentLimit << 5;//125*32    }    else if(wVoltLoopTemp < -wInvCrrentLimit << 5)    {        wVoltLoopTemp = -wInvCrrentLimit << 5;    }	//电压环比例-------------------------end--------------------------------------*/    //wRVBeforeSaturation = wVoltLoopTemp;// + wRLoadCurrCntl;//wRKv = 10;//采样做前馈    //if((hoInv1Relay == 1)&&(hoInv1Relay == 2))    if(hoInv1Relay == 1)	{    	wRVBeforeSaturation = wVoltLoopTemp + wInvCurrFeedValue*sinf(fNewSinPointer*0.01636f);//加电流前馈    }	else	{		wRVBeforeSaturation = wVoltLoopTemp;	}    if(wRVBeforeSaturation > wInvCrrentLimit<<5)    {        wRVBeforeSaturation = wInvCrrentLimit<<5;//125*32    }    else if(wRVBeforeSaturation < -wInvCrrentLimit<<5)    {        wRVBeforeSaturation = -wInvCrrentLimit<<5;    }    wRInvCurrError = wRVBeforeSaturation - wRInvCurrCntl;    dwRK1_1 = ((INT32S)(wRInvCurrError)*wRKi >> 7);//wRKi=220    dwRK1 = dwRK1_1;		    wInvLoopCntPre ++;//	//采样做前馈//    if(wInvLoopCntPre > 20000)//    {//		if(wVoltFeedK >= 1024)//		{//			wVoltFeedK = 1024;//		}//        else if((wInvLoopCntPre - wInvLoopCntLast)>50)//        {//            wVoltFeedK += 1;//            wInvLoopCntLast = wInvLoopCntPre;//        }//        if(wInvLoopCntPre > 30000)//        {//            wInvLoopCntPre = 30000;//        }//    }//    else//    {//        wVoltFeedK = 940;//    }//	dwRVoltLimit = dwRK1  + ((INT32S)wRInvVoltCntl * (INT32S)wVoltFeedK >> 10);//	//dwRVoltLimit = dwRK1	+ ((INT32S)(SogiInvVolt.fOsgAcAlpha[0]*16008.0 - wInvVoltDcSamp) * (INT32S)wVoltFeedK >> 10);//	//dwRVoltLimit = dwRK1	+ ((INT32S)((F32)wRInverterVoltNew*4.5248*sinf(fNewSinPointer*0.01636f) - wInvVoltDcSamp) * (INT32S)wVoltFeedK >> 10);//3.2*1.414	//参考做前馈    if(wInvLoopCntPre > 100)    {		if(wVoltFeedK >= 1024)		{			wVoltFeedK = 1024;		}        else if((wInvLoopCntPre - wInvLoopCntLast)>50)        {            wVoltFeedK += 1;            wInvLoopCntLast = wInvLoopCntPre;        }        if(wInvLoopCntPre > 30000)        {            wInvLoopCntPre = 20000;			wInvLoopCntLast = wInvLoopCntPre;        }    }    else    {        wVoltFeedK = 820;    }    dwRVoltLimit = dwRK1  + ((INT32S)((F32)wRSinAmp*sinf(fNewSinPointer*0.01636f)) * (INT32S)wVoltFeedK >> 10);	wRLoopOutput=(INT16S)((dwRVoltLimit * wKpwm) >> 12);//924>>12=0.22558    wR_PWM = wRLoopOutput;//	//#warn 开环发波//	if(wOpenSinRef < 1833)//	{//	    wOpenSinRef++;//	}//	wOpenSinRef = 1833;//  wR_PWM = (INT16S)(((INT32S)wOpenSinRef * pSinTab[wCtrlSinpointer] >> 14));	if(hoInv2Relay)	{		if((wCtrlSinpointer == 96)||(wCtrlSinpointer == 288))		{			uwInv2PwmOnFlag = 1;		}	}	else	{		uwInv2PwmOnFlag = 0;	}    if(wR_PWM >= 0)    {        wR_PWMTemp = wR_PWM + 1;        if(wR_PWMTemp > (wPwmPeriod - 201))        {            wR_PWMTemp = wPwmPeriod - 201;        }        if(((PriOCPFlag1 == 1)||(PriOCPFlag2 == 1))&&(wR_PWMTemp > 20))        {            wR_PWMTemp = 20;        }        #ifndef SAME_PWM_MODE        EPwm2Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;     //LU        EPwm2Regs.CMPB.bit.CMPB = 1;                           //RD        EPwm1Regs.CMPA.bit.CMPA = 1;                           //RU        EPwm1Regs.CMPB.bit.CMPB = wPwmPeriod-wR_PWMTemp-200;   //LD        EPwm4Regs.CMPA.bit.CMPA = wR_PWMTemp;                  //LU        EPwm4Regs.CMPB.bit.CMPB = wPwmPeriod - 1;              //RD        EPwm3Regs.CMPA.bit.CMPA = wPwmPeriod - 1;              //RU        EPwm3Regs.CMPB.bit.CMPB = wR_PWMTemp+200;              //LD        #else        EPwm2Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;     //LU        EPwm2Regs.CMPB.bit.CMPB = 1;                           //RD        EPwm1Regs.CMPA.bit.CMPA = 1;                           //RU        EPwm1Regs.CMPB.bit.CMPB = wPwmPeriod-wR_PWMTemp-200;   //LD        EPwm4Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;     //LU        EPwm4Regs.CMPB.bit.CMPB = 1;                           //RD        EPwm3Regs.CMPA.bit.CMPA = 1;                           //RU        EPwm3Regs.CMPB.bit.CMPB = wPwmPeriod-wR_PWMTemp-200;   //LD        #endif        if(wLPWMForwardFlg != 0)        {            wLPWMForwardFlg = 0;			EPwm1Regs.AQCSFRC.all = 0x01;			EPwm2Regs.AQCSFRC.all = 0x08;			if(uwInv2PwmOnFlag == 1)			{		        EPwm3Regs.AQCSFRC.all = 0x01;				EPwm4Regs.AQCSFRC.all = 0x09;			}			else			{				EPwm3Regs.AQCSFRC.all = 0x05;				EPwm4Regs.AQCSFRC.all = 0x05;			}        }		else		{			EPwm1Regs.AQCSFRC.all = 0x01;			EPwm2Regs.AQCSFRC.all = 0x08;			if(uwInv2PwmOnFlag == 1)			{		        EPwm3Regs.AQCSFRC.all = 0x01;				EPwm4Regs.AQCSFRC.all = 0x08;			}			else			{				EPwm3Regs.AQCSFRC.all = 0x05;				EPwm4Regs.AQCSFRC.all = 0x05;			}		}		//EPwm3Regs.AQCSFRC.all = 0x05;		//EPwm4Regs.AQCSFRC.all = 0x05;    }    else	{		//判断变压器反接		if(wInvVoltReal>500)//50V         {            if(++IsoReverseCnt>50)//            {                IsoReverseCnt =0;                IsoReverseFlag =1;                IsoReverseRecoverCnt =0;				if(++IsoReverseChkCnt>60)//  60/2=30  60个市电周期以后才检???				{                    IsoReverseChkCnt =60;                    wFaultCode = eInvTXReverse;					swSetInvTxtRevConnectFault(true);                    OSISREventSend(cPrioSuper,eSuperFault);                }            }        }        else if(wInvVoltReal< -500)//50V        {            if((IsoReverseFlag)&&(++IsoReverseRecoverCnt>20))            {                IsoReverseCnt =0;                IsoReverseChkCnt =0;                IsoReverseFlag =0;                IsoReverseRecoverCnt =0;				swSetInvTxtRevConnectFault(false);            }        }        wR_PWMNegtive = -wR_PWM;        wR_PWMTemp = wR_PWMNegtive + 1;        if(wR_PWMTemp > (wPwmPeriod - 201))        {            wR_PWMTemp = wPwmPeriod - 201;        }        if(((PriOCPFlag1 == 1)||(PriOCPFlag2 == 1))&&(wR_PWMTemp > 20))        {            wR_PWMTemp = 20;        }        #ifndef SAME_PWM_MODE        EPwm2Regs.CMPA.bit.CMPA =  wPwmPeriod - 1;        //L        EPwm2Regs.CMPB.bit.CMPB =  wR_PWMTemp + 200;        EPwm1Regs.CMPA.bit.CMPA = wR_PWMTemp;               //R        EPwm1Regs.CMPB.bit.CMPB =  wPwmPeriod - 1;        EPwm4Regs.CMPA.bit.CMPA = 1;//R        EPwm4Regs.CMPB.bit.CMPB =  wPwmPeriod - wR_PWMTemp-200;        EPwm3Regs.CMPA.bit.CMPA =  wPwmPeriod - wR_PWMTemp;        //L        EPwm3Regs.CMPB.bit.CMPB =  1;        #else        EPwm2Regs.CMPA.bit.CMPA =  wPwmPeriod - 1;        //L        EPwm2Regs.CMPB.bit.CMPB =  wR_PWMTemp + 200;        EPwm1Regs.CMPA.bit.CMPA = wR_PWMTemp;               //R        EPwm1Regs.CMPB.bit.CMPB =  wPwmPeriod - 1;        EPwm4Regs.CMPA.bit.CMPA =  wPwmPeriod - 1;        //L        EPwm4Regs.CMPB.bit.CMPB =  wR_PWMTemp + 200;        EPwm3Regs.CMPA.bit.CMPA = wR_PWMTemp;               //R        EPwm3Regs.CMPB.bit.CMPB =  wPwmPeriod - 1;        #endif        if(wLPWMForwardFlg != 1)        {            wLPWMForwardFlg = 1;            EPwm1Regs.AQCSFRC.all = 0x09;	        EPwm2Regs.AQCSFRC.all = 0x01;			if(uwInv2PwmOnFlag == 1)			{				EPwm3Regs.AQCSFRC.all = 0x08;				EPwm4Regs.AQCSFRC.all = 0x01;			}			else			{				EPwm3Regs.AQCSFRC.all = 0x05;				EPwm4Regs.AQCSFRC.all = 0x05;			}        }		else		{			EPwm1Regs.AQCSFRC.all = 0x08;	        EPwm2Regs.AQCSFRC.all = 0x01;			if(uwInv2PwmOnFlag == 1)			{				EPwm3Regs.AQCSFRC.all = 0x08;				EPwm4Regs.AQCSFRC.all = 0x01;			}			else			{				EPwm3Regs.AQCSFRC.all = 0x05;				EPwm4Regs.AQCSFRC.all = 0x05;			}		}		//EPwm3Regs.AQCSFRC.all = 0x05;		//EPwm4Regs.AQCSFRC.all = 0x05;    }}void sInverterTest(void){    static INT16U wSoftCnt = 0;	INT16S wDeadTime = 0;    if(++wSoftCnt >= 10)    {        wSoftCnt = 0;        if(wOpenSinRef < 1833)        {            wOpenSinRef++;        }    }    if(wOpenSinRef > 1833)    {        wOpenSinRef = 1833;    }	//hoInv1RelayOn;	//hoInv2RelayOn;    wRLoopOutput = (INT16S)(((INT32S)wOpenSinRef * pSinTab[wCtrlSinpointer] >> 14));    wR_PWM = wRLoopOutput;	wDeadTime = 101;    if(wR_PWM > (wPwmPeriod - wDeadTime))   wR_PWM = wPwmPeriod - wDeadTime;    if(wR_PWM < -(wPwmPeriod - wDeadTime))   wR_PWM = -(wPwmPeriod -wDeadTime);	wDeadTime = 100;	    if(wR_PWM >= 0)    {        wR_PWMTemp = wR_PWM;        EPwm2Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;     //LU        EPwm2Regs.CMPB.bit.CMPB = 1;                           //RD        EPwm1Regs.CMPA.bit.CMPA = wDeadTime;                         //RU        EPwm1Regs.CMPB.bit.CMPB = wPwmPeriod-wR_PWMTemp-wDeadTime;   //LD        EPwm4Regs.CMPA.bit.CMPA = wR_PWMTemp;     //LU        EPwm4Regs.CMPB.bit.CMPB = wPwmPeriod - 1;                           //RD        EPwm3Regs.CMPA.bit.CMPA = wR_PWMTemp - wDeadTime;                         //RU        EPwm3Regs.CMPB.bit.CMPB = wR_PWMTemp+wDeadTime;   //LD        if(wLPWMForwardFlg != 0)        {            wLPWMForwardFlg = 0;			EPwm2Regs.AQCSFRC.all = 0x08;	        EPwm4Regs.AQCSFRC.all = 0x09;	        EPwm1Regs.AQCSFRC.all = 0x01;	        EPwm3Regs.AQCSFRC.all = 0x01;        }		else		{			EPwm2Regs.AQCSFRC.all = 0x08;	        EPwm4Regs.AQCSFRC.all = 0x08;	        EPwm1Regs.AQCSFRC.all = 0x01;	        EPwm3Regs.AQCSFRC.all = 0x01;		}    }    else    {        wR_PWMNegtive = -wR_PWM;        wR_PWMTemp = wR_PWMNegtive;        EPwm2Regs.CMPA.bit.CMPA =  wPwmPeriod - wDeadTime;                     //L        EPwm2Regs.CMPB.bit.CMPB =  wR_PWMTemp + wDeadTime;        EPwm1Regs.CMPA.bit.CMPA = wR_PWMTemp;//R        EPwm1Regs.CMPB.bit.CMPB =  wPwmPeriod - 1;        EPwm4Regs.CMPA.bit.CMPA = wDeadTime;//R        EPwm4Regs.CMPB.bit.CMPB =  wPwmPeriod - wR_PWMTemp-wDeadTime;        EPwm3Regs.CMPA.bit.CMPA =  wPwmPeriod - wR_PWMTemp;                     //L        EPwm3Regs.CMPB.bit.CMPB =  1;        if(wLPWMForwardFlg != 1)        {            wLPWMForwardFlg = 1;            EPwm1Regs.AQCSFRC.all = 0x09;	        EPwm3Regs.AQCSFRC.all = 0x08;	        EPwm2Regs.AQCSFRC.all = 0x01;	        EPwm4Regs.AQCSFRC.all = 0x01;        }		else		{			EPwm1Regs.AQCSFRC.all = 0x08;	        EPwm3Regs.AQCSFRC.all = 0x08;	        EPwm2Regs.AQCSFRC.all = 0x01;	        EPwm4Regs.AQCSFRC.all = 0x01;		}    }}void sFBINVPFCInitial(void){    if((g_wVAType == cb2000VAModel) \        || (g_wVAType == cb2500VAModel) \        || (g_wVAType == cb3500VAModel) \        || (g_wVAType == cb4000VAModel) \        || (g_wVAType == cb5000VAModel) \        || (g_wVAType == cb7500VAModel) \        || (g_wVAType == cb10KVAModel)  \        || (g_wVAType == cb15KVAModel))    {        wFBKVoltageForward = 50;//25;//50;//4*32;// 4*Q5  //12 while 4*32,FB  feeding 3000w,bus is not statable.        wFBKvn_1 = 78037/10;        wFBKvn_2 = 77644/10;        wFBKvd_1 = 15606;        wFBKvd_2 = 7414;        wFBVm_P_res = 0;        wFBP_KVinComp = 4096;     //voltage compensation        wFBKCurrentFeedback = 7;  //7*???????(100)=700,??????700        dwInvCurrLimit = 7488;      //5000w  linerms=230v maxcurr = 30*58/linerms*1.414*700=7488        dwInvCurrLimitAdj = 7488;        wFBKcd_1 = 9912;        wFBKcd_2 = 1717;        wFBKcn_0 = 11985;        wFBKcn_1 = 3367;        wFBKcn_2 = 8618;        wFBR_Vcmp_P_res = 0;        wR_PWM = wR_PWMTemp = wR_PWMNegtive = 0;        dwFBR_Ierr_P_0=dwFBR_Ierr_P_1 = dwFBR_Ierr_P=dwFBR_Vcmp_P_1 = dwFBR_Vcmp_P_2 = dwFBR_Vcmp_P = wFBR_Vcmp_P_res=0;        wFBVerr = wFBVerr_P = dwFBVerr_I1 = dwFBVerr_I = 0;        wKpwm = 924;           //Q7  2600/360*128        wRNewSinAmp=wRSinAmp = 0;//10407;      //Q5  230*1.414*32        wBatVSet = wBatVoltRef = cBat54v;        wFBKCurrentForward = 6;//5;//3;//4;  //Breeze 2016.1.29        //wRKvBase = wRKv = 40;//45;//48;//23;//10;   //48;             //Q7  0.18*128        wRKvBase = wRKv = 20;//45;//48;//23;//10;   //48;             //Q7  0.18*128        //wRKiBase = wRKi = 400;//320;//300;//274;   //250;           //Q7  8*128//        wRKiBase = wRKi = 200;        wMovePoint = 0;        wDeltaK=0;        wChgKp = 2000;        wVoltLoopKi=0;        wVoltLoopTemp  = 0;        wInvVoltVerr_P = fInvVoltVerr_I =0;        wRRepetCtrlUp = 1600;//640;   //Q5 20*32 //Q5 62.5*32        wRRepetCtrUnder = -1600;//-640;        wRRctrlFvalue = 178;    //150;    //Q8 0.6*256 //George 141217 180->178        wKRctrl1 = 197;        //Q8 0.7711*2^8        wKRctrl2 = 29;         //Q8 0.1832*256    }    else    {        wFBKVoltageForward = 50;//25;//50;//4*32;// 4*Q5  //12 while 4*32,FB  feeding 3000w,bus is not statable.        wFBKvn_1 = 78037/10;        wFBKvn_2 = 77644/10;        wFBKvd_1 = 15606;        wFBKvd_2 = 7414;        wFBVm_P_res = 0;        wFBP_KVinComp = 4096;     //voltage compensation        wFBKCurrentFeedback = 7;  //7*???????(100)=700,??????700        dwInvCurrLimit = 7488;      //5000w  linerms=230v maxcurr = 30*58/linerms*1.414*700=7488        dwInvCurrLimitAdj = 7488;        wFBKcd_1 = 10297;        wFBKcd_2 = 2104;        wFBKcn_0 = 11780;        wFBKcn_1 = 2165;        wFBKcn_2 = 9617;        wFBR_Vcmp_P_res = 0;        wR_PWM = wR_PWMTemp = wR_PWMNegtive = 0;        dwFBR_Ierr_P_0=dwFBR_Ierr_P_1 = dwFBR_Ierr_P=dwFBR_Vcmp_P_1 = dwFBR_Vcmp_P_2 = dwFBR_Vcmp_P = wFBR_Vcmp_P_res=0;        wFBVerr = wFBVerr_P = dwFBVerr_I1 = dwFBVerr_I = 0;        wKpwm = 924;           //Q7  2600/360*128        wRNewSinAmp=wRSinAmp = 0;//10407;      //Q5  230*1.414*32        wBatVSet = wBatVoltRef = cBat54v;        wFBKCurrentForward = 3;//5;//3;//4;  //8 while bus 150V//Q7        wRKvBase = wRKv = 48;//23;//10;   //48;             //Q7  0.18*128        wRKiBase = wRKi = 305;   //250;           //Q7  8*128//  305        wMovePoint = 0;        //wDeltaK=128;        wDeltaK=0;        wChgKp = 2000;        wVoltLoopKi=0;        wVoltLoopTemp  = 0;        wInvVoltVerr_P = fInvVoltVerr_I =0;        wRRepetCtrlUp = 1600;//640;   //Q5 20*32 //Q5 62.5*32        wRRepetCtrUnder = -1600;//-640;        wRRctrlFvalue = 180;    //150;    //Q8 0.6*256        wKRctrl1 = 197;        //Q8 0.7711*2^8        wKRctrl2 = 29;         //Q8 0.1832*256    }}void sClearFBRam(void){    wFBCtrlSwitch = true;    wFBCntLoop = 0;    dwFBBatRealAvgSum = 0;    dwFBImo_P = 0;    wFBR_Vcmp_P_res = 0;    wR_PWM = wR_PWMTemp = wR_PWMNegtive = 0;    dwFBR_Ierr_P_0=dwFBR_Ierr_P_1 = dwFBR_Ierr_P=dwFBR_Vcmp_P_1 = dwFBR_Vcmp_P_2 = dwFBR_Vcmp_P = wFBR_Vcmp_P_res=0;    wFBVerr = wFBVerr_P = dwFBVerr_I1 = dwFBVerr_I = dwFBVerr_I = dwFBVerr_I1 = 0;    wNPWMForwardFlg = 2;    wLPWMForwardFlg = 2;    wVoltLoopTemp  = 0;    wInvVoltVerr_P = fInvVoltVerr_I=0 ;    dwRK1 = 0;    dwFBVm_P = 0;    g_wFBCtrlStartCycle = true;    g_wFBCtrlStartPoint = 0;    wChgPwm = 0;    wChgPwmLimit = 0;    wDisChgPwm = 0;    g_bDischgFlag = false;    wOpenSinRef = 0;    wInvLoopCntPre = 0;	wInvLoopCntLast = 0;    wVoltFeedK = 900;    wVmUpLimit = 500;    fAcDisChgCurrLoopI = 0.0f;    fAcDisChgCurrLoopOut = 0.0f;    fDisChgCurrLoopPI = 0.0f;    fDisChgCurrLoopErr0 = 0.0f;    fDisChgCurrLoopErr1 = 0.0f;    fDisChgCurrLoopErr2 = 0.0f;    fDisChgCurrLoopOut0 = 0.0f;    fDisChgCurrLoopOut1 = 0.0f;    fDisChgCurrLoopOut2 = 0.0f;    fNewSinPointerDelta = 0.0f;    fDisChgCurrLoopI = 0.0f;    fInvVoltLoopPI = 0.0f;    fInvVoltLoopErr0 = 0.0f;    fInvVoltLoopErr1 = 0.0f;    fInvVoltLoopErr2 = 0.0f;    fInvVoltLoopOut0 = 0.0f;    fInvVoltLoopOut1 = 0.0f;    fInvVoltLoopOut2 = 0.0f;    fInvVoltVerr_I = 0.0f;	fLoadPowerPLoopI = 0.0f;	fLoadPowerQLoopI = 0.0f;	wVoltRmsLoopI = 0;	wInvVoltCompValueReal = 0;    wInvVoltCompValueTemp = 0;}void sFBINVController(void){    INT16S wTemp1 = 0, wPwmTemp;    wR_PWM = wChgPwmLimit;#ifdef  ChgOPENLOOP    wR_PWM = (INT16S)(((INT32S)wPwmPeriod * 5 / 100));#endif    if(true == g_bDischgFlag)    {        wTemp1 = (INT16S)(((INT32S)wPwmPeriod * 973) >> 10);        if(wR_PWM >  wTemp1) wR_PWM =  wTemp1;        if(wR_PWM < -wTemp1) wR_PWM = -wTemp1;        wPwmTemp = (INT16S)(((INT32S)wR_PWM * pSinTab[wCtrlSinpointer] >> 14));        if(wLineVoltReal < 0)        {            if(wPwmTemp > 0)            {                wPwmTemp = 0;            }            wR_PWMTemp = abs(wPwmTemp);            EPwm2Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;  //L            EPwm4Regs.CMPA.bit.CMPA = wR_PWMTemp;               //L            EPwm1Regs.CMPA.bit.CMPA = wPwmPeriod - 1;           //R            EPwm3Regs.CMPA.bit.CMPA = 1;                        //R            if(wLPWMForwardFlg != 0)            {                wLPWMForwardFlg = 0;                //EPwm2Regs.AQCSFRC.bit.CSFA = 1;                //EPwm2Regs.AQCSFRC.bit.CSFB = 1;                EPwm2Regs.AQCSFRC.all = 0x05;                EPwm4Regs.AQCSFRC.all = 0x05;            }            else            {                //EPwm2Regs.AQCSFRC.bit.CSFA = 0;                //EPwm2Regs.AQCSFRC.bit.CSFB = 1;                EPwm2Regs.AQCSFRC.all = 0x04;                EPwm4Regs.AQCSFRC.all = 0x04;            }            if(wNPWMForwardFlg != 0)            {                wNPWMForwardFlg = 0;                //EPwm1Regs.AQCSFRC.bit.CSFA = 1;                //EPwm1Regs.AQCSFRC.bit.CSFB = 1;                EPwm1Regs.AQCSFRC.all = 0x05;                EPwm3Regs.AQCSFRC.all = 0x05;            }            else            {                //EPwm1Regs.AQCSFRC.bit.CSFA = 1;                //EPwm1Regs.AQCSFRC.bit.CSFB = 2;                EPwm1Regs.AQCSFRC.all = 0x09;                EPwm3Regs.AQCSFRC.all = 0x09;            }        }        else        {            if(wPwmTemp < 0)            {                wPwmTemp = 0;            }            wR_PWMTemp = abs(wPwmTemp);            EPwm2Regs.CMPB.bit.CMPB = wPwmPeriod - wR_PWMTemp;  //L            EPwm4Regs.CMPB.bit.CMPB = wR_PWMTemp;               //L            EPwm1Regs.CMPA.bit.CMPA = wPwmPeriod - 1;           //R            EPwm3Regs.CMPA.bit.CMPA = 1;                        //R            if(wLPWMForwardFlg != 1)            {                wLPWMForwardFlg = 1;                //EPwm2Regs.AQCSFRC.bit.CSFA = 1;                //EPwm2Regs.AQCSFRC.bit.CSFB = 1;                EPwm2Regs.AQCSFRC.all = 0x05;                EPwm4Regs.AQCSFRC.all = 0x05;            }            else            {                //EPwm2Regs.AQCSFRC.bit.CSFA = 1;                //EPwm2Regs.AQCSFRC.bit.CSFB = 0;                EPwm2Regs.AQCSFRC.all = 0x01;                EPwm2Regs.AQCSFRC.all = 0x01;            }            if(wNPWMForwardFlg != 1)            {                wNPWMForwardFlg = 1;                //EPwm1Regs.AQCSFRC.bit.CSFA = 1;                //EPwm1Regs.AQCSFRC.bit.CSFB = 1;                EPwm1Regs.AQCSFRC.all = 0x05;                EPwm3Regs.AQCSFRC.all = 0x05;            }            else            {                //EPwm1Regs.AQCSFRC.bit.CSFA = 2;                //EPwm1Regs.AQCSFRC.bit.CSFB = 1;                EPwm1Regs.AQCSFRC.all = 0x06;                EPwm3Regs.AQCSFRC.all = 0x06;            }        }    }    else    {        wTemp1 = (INT16S)(((INT32S)wPwmPeriod * 512) >> 10);        if(wR_PWM >  wTemp1) wR_PWM =  wTemp1;        if(wR_PWM < -wTemp1) wR_PWM = -wTemp1;        wR_PWMTemp = wPwmPeriod - abs(wR_PWM);        EPwm2Regs.CMPB.bit.CMPB =  wR_PWMTemp;        EPwm1Regs.CMPB.bit.CMPB =  wR_PWMTemp;        EPwm4Regs.CMPB.bit.CMPB =  wPwmPeriod - wR_PWMTemp;        EPwm3Regs.CMPB.bit.CMPB =  wPwmPeriod - wR_PWMTemp;        EPwm2Regs.AQCSFRC.bit.CSFA = 1;        EPwm1Regs.AQCSFRC.bit.CSFA = 1;        EPwm4Regs.AQCSFRC.bit.CSFA = 1;        EPwm3Regs.AQCSFRC.bit.CSFA = 1;    }}extern INT16S gi_wKVinCompAvgPeak;extern INT16S gi_wKVGenCompAvgPeak;extern INT16S wInvLCurrSample1;INT16S TestVlotErr =164;INT16S wCurrFeedBack =0;INT16S wR_PFCPWM;INT16S g_wBatChgBusAvg;INT16S TestLineSet;INT16S wLineVoltRealOffSet=2000;INT16S wFB_CurPI_KiTest =164;INT16S wFB_CurPI_KpTest =70;INT16S wFB_CurDNTest=4;INT16S wFB_CurMOTest=11;F32 fFBBusVoltRef = 0;F32 fFBBusVoltAvgSum = 0;F32 fFBBusVoltError = 0;F32 fFBBusVoltErrorLast = 0;F32 fFBBusVoltLoopI = 0;//BUS电压环积分F32 fFBBusVoltLoopPI = 0;//BUS电压环比例积分F32 fFBInvChgCurrLimit = 0;//Inv电流限制值F32 fFBInvDisChgCurrLimit = 0;//Inv电流限制值void sFBINVController2(void){    INT16S wTemp1 = 0, wPwmTemp;	INT16S wCtrlSinpointerTemp=0;	INT16S wDeadTime = 0;	INT16S wLineVoltTemp = 0;    //g_bDischgFlag = true;      wR_PWM = wChgPwmLimit;    //wR_PWM = 100;    wTemp1 = (INT16S)(((INT32S)wPwmPeriod * 950) >> 10);    if(wR_PWM >  wTemp1) wR_PWM =  wTemp1;    if(wR_PWM < -wTemp1) wR_PWM = -wTemp1;    wPwmTemp = (INT16S)(((INT32S)wR_PWM * pSinTab[wCtrlSinpointer] >> 14));		if(gi_wIslandDetectStep)	// 孤岛默认不生效	//if(0)	{		if(wCtrlSinpointer < (wRCountsPerPeriod>>1))		{			wCtrlSinpointerTemp = (INT16S)((INT32S)wCtrlSinpointer * (gi_wIslandDetectStep + 50) / 50);			if(wCtrlSinpointerTemp > (wRCountsPerPeriod>>1))			{				wCtrlSinpointerTemp = wRCountsPerPeriod>>1;			}		}		else		{			wCtrlSinpointerTemp = (INT16S)(((INT32S)wCtrlSinpointer - (wRCountsPerPeriod>>1)) * \									(gi_wIslandDetectStep + 50) / 50) + (wRCountsPerPeriod>>1);			if(wCtrlSinpointerTemp > (wRCountsPerPeriod - 1))			{				wCtrlSinpointerTemp = (wRCountsPerPeriod - 1);			}		}		}	else	{		wCtrlSinpointerTemp = wCtrlSinpointer;//g_wRSinPointer;	}    //BUS电压环	fFBBusVoltAvgSum += wBatVoltReal;    if(++wFBCntLoop&0x08)    {        wFBCntLoop =0;        //fFBBusVoltError = (F32)swGetBatVoltRef()-fFBBusVoltAvgSum*0.125f;//0.1V        fFBBusVoltError = fFBBusVoltRef-fFBBusVoltAvgSum*0.125f;//0.1V        fFBBusVoltAvgSum =0;		if(fFBBusVoltError < -25)        {						if(fFBBusVoltAvgSum*0.125 > 610.0)			{				if(fFBBusVoltLoopI > 50.0)				{					fFBBusVoltLoopI = fFBBusVoltLoopI * 0.3f;				}				fFBBusVoltErrorLast = fFBBusVoltError;				fFBBusVoltLoopI += 0.0471f * fFBBusVoltError;				UP_DOWN_LIMIT(fFBBusVoltLoopI,fFBInvChgCurrLimit+10.0,-fFBInvDisChgCurrLimit);				fFBBusVoltLoopPI = fFBBusVoltLoopI + 6.0f * fFBBusVoltError;			}			else			{				fFBBusVoltErrorLast = fFBBusVoltError;				fFBBusVoltLoopI += 0.0196f * fFBBusVoltError;				UP_DOWN_LIMIT(fFBBusVoltLoopI,fFBInvChgCurrLimit+10.0,-fFBInvDisChgCurrLimit);				fFBBusVoltLoopPI = fFBBusVoltLoopI + 2.5f * fFBBusVoltError;			}			UP_DOWN_LIMIT(fFBBusVoltLoopPI,fFBInvChgCurrLimit,-fFBInvDisChgCurrLimit);        }		else		{			fFBBusVoltError = 0.895f*fFBBusVoltErrorLast+0.105f*fFBBusVoltError;        	fFBBusVoltErrorLast = fFBBusVoltError;			fFBBusVoltLoopI += 0.00785f * fFBBusVoltError;			UP_DOWN_LIMIT(fFBBusVoltLoopI,fFBInvChgCurrLimit+10.0,-fFBInvDisChgCurrLimit);			fFBBusVoltLoopPI = fFBBusVoltLoopI + 1.0f * fFBBusVoltError;			UP_DOWN_LIMIT(fFBBusVoltLoopPI,fFBInvChgCurrLimit,-fFBInvDisChgCurrLimit);		}		if((g_LineModeJoinInWay == cLineModeJoinInByGen)&&(fFBBusVoltLoopPI < 0.5))		{			fFBBusVoltLoopPI = 0.5; //防止向发电机馈电		}		    }	if(wBatVoltReal > 640)//>64V	{		if(fFBBusVoltLoopI > 50.0)		{			fFBBusVoltLoopI = fFBBusVoltLoopI * 0.3f;			fFBBusVoltLoopPI = fFBBusVoltLoopPI * 0.3f;		}	}	if(fFBBusVoltLoopI < fFBInvChgCurrLimit)	{		g_wChgCompPower = 0;	}	fDisChgCurrLoopRef = -(F32)(((INT32S)fFBBusVoltLoopPI *  pSinTab[wCtrlSinpointerTemp] >> 14));	//wInvCurrErr1 = wInvLCurrReal - (SogiInvCurr.fOsgAcAlpha[0] * 3063.8 + 0.5);    fDisChgCurrLoopErr2 = fDisChgCurrLoopErr1;    fDisChgCurrLoopErr1 = fDisChgCurrLoopErr0;    fDisChgCurrLoopOut2 = fDisChgCurrLoopOut1;    fDisChgCurrLoopOut1 = fDisChgCurrLoopOut0;    fDisChgCurrLoopErr0 = fDisChgCurrLoopRef - (F32)wInvLCurrReal-4;	fDisChgCurrLoopOut0 = fDisChgCurrLoopOut1*1.9932f-fDisChgCurrLoopOut2*0.9935f\						  + fDisChgCurrLoopErr0*2.0489f-fDisChgCurrLoopErr1*3.9864f\						  +fDisChgCurrLoopErr2*1.9381f;    UP_DOWN_LIMIT(fDisChgCurrLoopOut0,(F32)wTemp1,-(F32)wTemp1);	if(g_LineModeJoinInWay == cLineModeJoinInByGen)	{		wLineVoltTemp = (SogiGenVolt.fOsgAcAlpha[0]*5002.5f);		//wLineVoltTemp = 0;	}	else if(mGenConnectToGridEn)	{		wLineVoltTemp = (SogiLineVolt.fOsgAcAlpha[0]*5002.5f);	}	else 	{		wLineVoltTemp = wLineVoltReal;	}    fDisChgPwm = fDisChgCurrLoopOut0 + (F32)wLineVoltTemp*0.5;    UP_DOWN_LIMIT(fDisChgPwm,(F32)wTemp1,-(F32)wTemp1);	wDeadTime = 100;	//离网逆变发波	//if(fDisChgPwm > 0.0)	if(wLineVoltTemp > 5)	{		wPwmTemp = (INT16S)fDisChgPwm;		 if(wPwmTemp < 2)        {            wPwmTemp = 2;        }		wR_PWMTemp = wPwmTemp;        EPwm2Regs.CMPA.bit.CMPA = wPwmPeriod - wR_PWMTemp;     //LU        EPwm2Regs.CMPB.bit.CMPB = 1;                           //RD        EPwm1Regs.CMPA.bit.CMPA = 1;                         //RU        EPwm1Regs.CMPB.bit.CMPB = wPwmPeriod-wR_PWMTemp-wDeadTime;   //LD        EPwm4Regs.CMPA.bit.CMPA = wR_PWMTemp;     //LU        EPwm4Regs.CMPB.bit.CMPB = wPwmPeriod - 1;                           //RD        EPwm3Regs.CMPA.bit.CMPA = wR_PWMTemp - 1;                         //RU        EPwm3Regs.CMPB.bit.CMPB = wR_PWMTemp + wDeadTime;   //LD        if(wLPWMForwardFlg != 0)        {            wLPWMForwardFlg = 0;			EPwm2Regs.AQCSFRC.all = 0x08;	        EPwm4Regs.AQCSFRC.all = 0x09;	        EPwm1Regs.AQCSFRC.all = 0x01;	        EPwm3Regs.AQCSFRC.all = 0x01;        }		else		{			EPwm2Regs.AQCSFRC.all = 0x08;	        EPwm4Regs.AQCSFRC.all = 0x08;	        EPwm1Regs.AQCSFRC.all = 0x01;	        EPwm3Regs.AQCSFRC.all = 0x01;		}	}	else if(wLineVoltTemp < -5)	//else	{		wPwmTemp = (INT16S)fDisChgPwm;        if(wPwmTemp > -2)        {            wPwmTemp = -2;        }        wR_PWMTemp = -wPwmTemp;        EPwm2Regs.CMPA.bit.CMPA =  wPwmPeriod - 1;                     //L        EPwm2Regs.CMPB.bit.CMPB =  wR_PWMTemp + wDeadTime;        EPwm1Regs.CMPA.bit.CMPA = wR_PWMTemp;//R        EPwm1Regs.CMPB.bit.CMPB =  wPwmPeriod - 1;        EPwm4Regs.CMPA.bit.CMPA = 1;//R        EPwm4Regs.CMPB.bit.CMPB =  wPwmPeriod - wR_PWMTemp-wDeadTime;        EPwm3Regs.CMPA.bit.CMPA =  wPwmPeriod - wR_PWMTemp;                     //L        EPwm3Regs.CMPB.bit.CMPB =  1;        if(wLPWMForwardFlg != 1)        {            wLPWMForwardFlg = 1;            EPwm1Regs.AQCSFRC.all = 0x09;	        EPwm3Regs.AQCSFRC.all = 0x08;	        EPwm2Regs.AQCSFRC.all = 0x01;	        EPwm4Regs.AQCSFRC.all = 0x01;        }		else		{			EPwm1Regs.AQCSFRC.all = 0x08;	        EPwm3Regs.AQCSFRC.all = 0x08;	        EPwm2Regs.AQCSFRC.all = 0x01;	        EPwm4Regs.AQCSFRC.all = 0x01;		}	}    }void sChgVariableInit(void){    dwFBP_CurPI_I =0;    dwFBP_CurPI_I_Res =0;    wVmUpLimit =500;    dwFBP_VoltPI_I =0;    dwFBP_VoltPI_I_Res =0;    wFBP_VoltPIAdjCtl =0;	fFBBusVoltAvgSum = 0.0;	fFBBusVoltError = 0.0;	fFBBusVoltErrorLast = 0.0;	fFBBusVoltLoopI = 0.0;//BUS电压环积分	fFBBusVoltLoopPI = 0.0;//BUS电压环比例积分}INT16S wInvVoltRmsSet;INT16S wInvVoltRmsReal;//void sParaAdjDataCal()//{//	//通过有效值计算将输出电压调到设置电压//    INT16S wInvVoltRmsError;//	//if((hoInvRLY == 1)&&(mEepromOutputMode() != cOP_Single)&&(wParaMode == cMasterMode))//	//if((hoInvRLY == 1)&&(mEepromOutputMode() != cOP_Single)&&(g_wPhaseMasterFlg))//	if((hoInv1Relay == 1)&&(g_wPhaseMasterFlg)&&(g_uwWorkMode == cBatteryMode))//	{//		wInvVoltRmsSet = ((INT32S)wRSinAmp * 905)>>12;//* 0.221f;//10/32/1.414;//		wInvVoltRmsReal = (INT16S)swGetRInverterVolt();//0.1V//		wInvVoltRmsError = wInvVoltRmsSet - wInvVoltRmsReal;//		if((wInvVoltRmsError < -50)&&(wInvVoltCompI > 0))//		{//			wInvVoltCompI = 0;//		}//		//wInvVoltCompI += ((wInvVoltRmsError * 1)>>2);//2电压做前馈//		wInvVoltCompI += ((wInvVoltRmsError * 1)>>2);//2电压做前馈//		//		if(wInvVoltCompI < -3200)//		{//			wInvVoltCompI = -3200;//		}//		else if(wInvVoltCompI > 24000)//		{//			wInvVoltCompI = 24000;//		}//		//		//		//wInvVoltCompValueTemp = wInvVoltCompI + ((wInvVoltRmsError * 1)>>6);//		wInvVoltCompValueTemp = wInvVoltCompI + ((wInvVoltRmsError * 1)>>1);//		//		if(wInvVoltCompValueTemp < -3200)//		{//			wInvVoltCompValueTemp = -3200;//		}//		else if(wInvVoltCompValueTemp > 24000)//		{//			wInvVoltCompValueTemp = 24000;//		}//	}//	else//	{//		wInvVoltCompI = 0;//		wInvVoltCompValueTemp = 0;//	}//    //wInvVoltCompValueTemp = 0;//    //if(wParaMode == cMasterMode)//  